function mkPackHtml(){ const btn=p=>`<button data-act="mk-add-pack" data-val="${p.id}" data-testid="mk-pack-${p.id}" aria-label="Add ${esc(p.name)}" title="${esc(p.name)}"><img src="${mkPackSrc(p.id)}" alt=""></button>`;
  return `<div class="mk-field"><p class="mk-lbl">Animated stickers <span class="mk-new-tag">Live</span></p><div class="mk-pack-grid" data-testid="mk-pack-grid-anim">${MK_PACK.filter(p=>p.anim).map(btn).join('')}</div></div><div class="mk-field"><p class="mk-lbl">Treesh sticker pack</p><div class="mk-pack-grid" data-testid="mk-pack-grid">${MK_PACK.filter(p=>!p.anim).map(btn).join('')}</div></div>`; }
function mkMotionNewHtml(){ const v=state.mkMotionNew||'auto'; return `<div class="mk-field"><p class="mk-lbl">Move to the beat</p>${mkSeg('mk-motion-new',v,[['auto','Auto']].concat(MK_MOTIONS),'mk-motion-new').replace('class="mk-seg"','class="mk-seg mk-seg-wrap mk-seg-motion"')}<p class="mk-hint">New stickers react to the real beat of whatever is playing.</p></div>`; }
function mkVizColor(mode,i,n){ if(mode==='white') return 'rgba(255,255,255,.92)'; if(mode==='rainbow') return `hsl(${Math.round(i/n*300+(performance.now()/40))%360} 90% 62%)`; return _mkVizAcc; }
let _mkVizAcc='#9328ff', _mkVizAccT=0;
function mkVizDraw(list,now,bins,playing,e){ if(now-_mkVizAccT>800){ _mkVizAccT=now; _mkVizAcc=(getComputedStyle(document.documentElement).getPropertyValue('--treesh-purple')||'#9328ff').trim()||'#9328ff'; }
  list.forEach(cv=>{ const dpr=Math.min(2,window.devicePixelRatio||1); const W=Math.round(cv.clientWidth*dpr), H=Math.round(cv.clientHeight*dpr); if(!W||!H) return; if(cv.width!==W||cv.height!==H){ cv.width=W; cv.height=H; }
    const ctx=cv.getContext('2d'); const N=cv.dataset.mkViz==='wave'?48:32; const mode=cv.dataset.vizColor||'accent'; const v=cv._v||(cv._v=new Float32Array(N));
    for(let i=0;i<N;i++){ let t; if(bins){ const k=Math.floor(Math.pow(i/N,1.6)*Math.min(bins.length,96)); t=bins[k]/255; } else t=playing?(0.25+0.75*Math.abs(Math.sin(now/1000*(1.2+i*.11)+i*1.9)))*(0.45+e*0.55):0.04+0.03*Math.sin(now/900+i*.5); v[i]+=(t-v[i])*(t>v[i]?.45:.12); }
    ctx.clearRect(0,0,W,H); const st=cv.dataset.mkViz;
    if(st==='wave'){ ctx.lineWidth=3*dpr; ctx.lineJoin='round'; ctx.lineCap='round'; for(let pass=0;pass<2;pass++){ ctx.beginPath(); for(let i=0;i<N;i++){ const x=i/(N-1)*W; const y=H/2+(pass?-1:1)*v[i]*H*.42*Math.sin(i/(N-1)*Math.PI); if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y); } const g=ctx.createLinearGradient(0,0,W,0); g.addColorStop(0,mkVizColor(mode,0,N)); g.addColorStop(.5,mode==='accent'?'#ff2d78':mkVizColor(mode,N/2,N)); g.addColorStop(1,mkVizColor(mode,N,N)); ctx.strokeStyle=g; ctx.globalAlpha=pass?.55:1; ctx.stroke(); } ctx.globalAlpha=1; }
    else if(st==='orb'){ const cx=W/2, cy=H/2, R=Math.min(W,H)*.2*(1+e*.25); ctx.save(); ctx.translate(cx,cy); for(let i=0;i<N;i++){ const a=i/N*Math.PI*2; const L=R*.25+v[i]*Math.min(W,H)*.28; ctx.strokeStyle=mkVizColor(mode,i,N); ctx.lineWidth=Math.max(2,R*.12); ctx.lineCap='round'; ctx.beginPath(); ctx.moveTo(Math.cos(a)*R*1.08,Math.sin(a)*R*1.08); ctx.lineTo(Math.cos(a)*(R*1.08+L),Math.sin(a)*(R*1.08+L)); ctx.stroke(); } const g=ctx.createRadialGradient(0,0,R*.1,0,0,R); g.addColorStop(0,'rgba(255,255,255,.95)'); g.addColorStop(1,mkVizColor(mode,0,N)); ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,R,0,Math.PI*2); ctx.fill(); ctx.restore(); }
    else { const gap=W/N*.28, bw=W/N-gap; for(let i=0;i<N;i++){ const h=Math.max(4*dpr,v[i]*H*.96); const x=i*(bw+gap)+gap/2; ctx.fillStyle=mkVizColor(mode,i,N); const r=Math.min(bw/2,8*dpr); ctx.beginPath(); if(ctx.roundRect) ctx.roundRect(x,H-h,bw,h,[r,r,2,2]); else ctx.rect(x,H-h,bw,h); ctx.fill(); } } }); }
function mkReactLoop(){ if(_mkRAF||state.perfMode||!document.querySelector('.mk-react,.mk-glow-beat,[data-mk-viz]')) return;
  const tick=now=>{ const list=document.querySelectorAll('.mk-react'), pages=document.querySelectorAll('.mk-glow-beat'), viz=document.querySelectorAll('[data-mk-viz]');
    if((!list.length&&!pages.length&&!viz.length)||state.perfMode){ _mkRAF=null; return; }
    const dt=Math.min(0.05,Math.max(0,(now-(_bt.t||now))/1000)); _bt.t=now; let lvl=0, hit=false, real=false; const playing=!!state.isPlaying;
    if(playing){ if(!_vizAnalyser&&!_bt.tried){ _bt.tried=true; try{ if(ensureVizAudio()) vizResume(); }catch(_){} }
      if(_vizAnalyser&&_vizBytes){ try{ _vizAnalyser.getByteFrequencyData(_vizBytes); let s=0; for(let i=1;i<7;i++) s+=_vizBytes[i]; lvl=s/6/255; real=true; }catch(_){} }
      _bt.zero=(real&&lvl===0)?_bt.zero+dt:0;
      if(!real||_bt.zero>2){ real=false; const ph=(now/500)%1; lvl=Math.pow(1-ph,3)*0.85; }
      _bt.avg=_bt.avg*0.94+lvl*0.06; if(lvl>_bt.avg*1.2+0.04&&lvl>0.2&&now-_bt.last>230){ hit=true; _bt.last=now; } }
    _bt.env=hit?1:_bt.env*Math.pow(0.015,dt); const e=Math.max(_bt.env,playing?lvl*0.5:0);
    _bt.spin=(_bt.spin+dt*(playing?(36+lvl*320+_bt.env*260):0))%360; const T=now/1000;
    const vars=[['--beat',(1+e*0.26).toFixed(3)],['--bounce',(e*24).toFixed(1)+'px'],['--wig',(playing?Math.sin(T*13)*(2+e*16):0).toFixed(1)+'deg'],['--spin',_bt.spin.toFixed(1)+'deg'],['--e',e.toFixed(3)],['--flt',(Math.sin(T*2.1)*(5+e*12)).toFixed(1)+'px'],['--sh',(playing?Math.sin(T*44)*e*7:0).toFixed(1)+'px'],['--swg',(Math.sin(T*(playing?3.2:1.6))*(playing?8+e*16:5)).toFixed(1)+'deg']];
    list.forEach(el=>{ const st=el.style; vars.forEach(v=>st.setProperty(v[0],v[1])); });
    pages.forEach(el=>el.style.setProperty('--e',vars[4][1]));
    if(viz.length) mkVizDraw(viz,now,real?_vizBytes:null,playing,e);
    _mkRAF=requestAnimationFrame(tick); };
  _mkRAF=requestAnimationFrame(tick); }

/* ---------- P8: Magic Markup actions + inputs ---------- */
function mkAct8(act,t){ const val=t.dataset.val, id=t.dataset.id;
  switch(act){
    case 'mk-look': mkApplyLook(val); break;
    case 'mk-bg': if(val==='photo'){ const f=document.getElementById('mk-bg-file'); if(f) f.click(); } else mkThSet(val==='color'?{bg:'color',color:(mkTheme(mkCurPage())||{}).color||'#2a0f4d'}:{bg:val==='none'?'':val,dim:''}); break;
    case 'mk-bg-edit': { const T=mkTheme(mkCurPage())||{}; const src=T.photo&&_mkImgs[String(T.photo).slice(4)]; if(src) mkBgStudio(src,false,'Edit background'); break; }
    case 'mk-th-accent': mkThSet({accent:val}); break;
    case 'mk-th-font': mkThSet({font:val}); break;
    case 'mk-th-surf': mkThSet({surf:val==='default'?'':val}); break;
    case 'mk-th-glow': mkThSet({glow:val==='off'?'':val}); break;
    case 'mk-th-reset': { const page=mkCurPage(); if(!page) break; delete mkPage(page).theme; assetDel('mk_bg_'+page).catch(()=>{}); delete _mkImgs['mk_bg_'+page]; mkSave(); renderView(); mkRenderSheet(); toast('Theme reset',MK_PAGE_LABEL[page]+' is back to the app look'); break; }
    case 'mk-snap': { const m=mkS(); m.snap=!m.snap; mkSave(); renderView(); mkRenderSheet(); toast(m.snap?'Snap to grid on':'Snap to grid off'); break; }
    case 'mk-ly-sel': { mkSelect(id); const el=mkBlockEl(id); if(el) el.scrollIntoView({behavior:'smooth',block:'center'}); break; }
    case 'mk-ly-move': state.mkSel=id; mkMove(val); break;
    case 'mk-ly-hide': mkHideToggle(id); mkRenderSheet(); break;
    case 'mk-ly-st': { const f=mkFind(id); if(!f) break; state.mkStSel=id; state.mkSheet='sticker-edit'; renderView(); mkRenderSheet(); const el=document.querySelector('#view [data-mk-st="'+id+'"]'); if(el) el.scrollIntoView({behavior:'smooth',block:'center'}); break; }
    case 'mk-ly-st-lock': { const f=mkFind(id); if(!f) break; f.s.locked=!f.s.locked; if(!f.s.locked) delete f.s.locked; mkSave(); renderView(); mkRenderSheet(); toast(f.s.locked?'Sticker locked':'Sticker unlocked'); break; }
    case 'mk-st-lock': { const f=mkFind(state.mkStSel); if(!f) break; const on=!f.s.locked; if(on) f.s.locked=true; else delete f.s.locked; mkSave(); renderView(); mkRenderSheet(); toast(on?'Locked in place':'Unlocked','You can drag it again'); break; }
    case 'mk-st-pin': { const f=mkFind(state.mkStSel); if(!f) break; const s=f.s; const el=document.querySelector('#view [data-mk-st="'+s.id+'"]'); if(val==='page'){ if(el&&s.cv) mkStToPage(s,el); s.free=true; } else { delete s.free; if(el) mkStReparent(s,el); } mkSave(); renderView(); mkRenderSheet(); toast(val==='page'?'Floating on the page':'Locked to its section'); break; }
    case 'mk-wcfg': { const w=mkCurWidget(state.mkSel); if(!w) break; w[t.dataset.key]=val; mkSave(); mkWRefreshId(w.id); mkRenderSheet(); break; }
    case 'mk-quote-next': { const w=mkCurWidget(id); if(!w) break; w.qi=((+w.qi||0)+1)%MK_QUOTES.length; mkSave(); mkWRefreshId(id); break; }
  } }
document.addEventListener('click',e=>{ const t=e.target&&e.target.closest&&e.target.closest('[data-act]'); if(!t) return; const a=t.dataset.act; if(a&&a.indexOf('mk-')===0) mkAct8(a,t); });
document.addEventListener('input',e=>{ const el=e.target; if(!el||!el.dataset) return;
  if(el.dataset.mkWcfg){ const w=mkCurWidget(state.mkSel); if(!w) return; w[el.dataset.mkWcfg]=el.value.slice(0,el.dataset.mkWcfg==='text'?280:60); mkSaveSoon(); mkWRefreshId(w.id); return; }
  const k=el.dataset.mkTh; if(!k) return; const page=mkCurPage(); if(!page) return; const P=mkPage(page); const T=P.theme||(P.theme={}); try{ if(el.type==='range') fillSlider(el); }catch(_){}
  if(k==='dim'){ T.dim=+el.value; const d=document.querySelector('#mk-pbg .mk-pbg-dim'); if(d) d.style.opacity=T.dim/100; const v=document.getElementById('mk-th-dim-val'); if(v) v.textContent=T.dim+'%'; }
  else if(k==='blur'){ T.blur=+el.value; const b=document.querySelector('#mk-pbg .mk-pbg-base'); if(b){ b.style.filter=T.blur?'blur('+T.blur+'px)':''; b.style.inset=T.blur?(-T.blur*2)+'px':''; } const v=document.getElementById('mk-th-blur-val'); if(v) v.textContent=T.blur+'px'; }
  else if(k==='color'){ T.color=el.value; T.bg='color'; const b=document.querySelector('#mk-pbg .mk-pbg-base'); if(b) b.style.background=el.value; const l=el.closest('label'); if(l) l.style.background=el.value; }
  else if(k==='accent'){ T.accent=el.value; _mkAccNow=el.value; try{ applyAccent(el.value); }catch(_){} const l=el.closest('label'); if(l) l.style.background=el.value; }
  mkSaveSoon(); });
document.addEventListener('change',e=>{ const t=e.target; if(!t) return;
  if(t.id==='mk-bg-file'){ const f=t.files&&t.files[0]; t.value=''; if(!f) return; if(!/^image\//.test(f.type||'')&&!/\.(heic|heif)$/i.test(f.name||'')){ toast('Pick an image file'); return; } if(f.size>25*1024*1024){ toast('Image too large','Use one under 25 MB'); return; } mkBgStudio(URL.createObjectURL(f),true); return; }
  if(t.dataset&&(t.dataset.mkTh==='color'||t.dataset.mkTh==='accent'||t.dataset.mkTh==='blur')){ mkSave(); _mkBgKey=''; renderView(); mkRenderSheet(); }
  if(t.dataset&&t.dataset.mkWcfg==='at'){ mkSave(); mkRenderSheet(); } });
function p8MkInit(){ try{ loadGoogleFont('Caveat:wght@500;700'); }catch(e){}
  const pages=mkS().pages; const keys=Object.keys(pages).filter(k=>pages[k]&&pages[k].theme&&pages[k].theme.photo).map(k=>String(pages[k].theme.photo).slice(4));
  if(keys.length) Promise.all(keys.map(k=>assetGet(k).then(v=>{ if(v) _mkImgs[k]=v; }).catch(()=>{}))).then(()=>{ _mkBgKey=''; mkThemeApply(true); });
  setInterval(mkCdTick,1000);
  try{ audio.addEventListener('timeupdate',mkLyricTick); ['play','pause','loadedmetadata','emptied'].forEach(ev=>audio.addEventListener(ev,()=>setTimeout(mkSongChanged,0))); }catch(e){} }
